CREATE OR REPLACE PACKAGE KHBHDBN_COMPARE_PKG AS
 TYPE T_CURSOR IS REF CURSOR;
 PROCEDURE GET_COMPARE(P_CURRENT_DATE IN VARCHAR2,P_COMPARE_DATE IN VARCHAR2,P_CATEGORY IN VARCHAR2 DEFAULT NULL,P_PAGE_SIZE IN NUMBER DEFAULT 100,P_PAGE_INDEX IN NUMBER DEFAULT 0,P_OUT_CURSOR OUT T_CURSOR);
 PROCEDURE GET_SUMMARY(P_CURRENT_DATE IN VARCHAR2,P_COMPARE_DATE IN VARCHAR2,P_OUT_CURSOR OUT T_CURSOR);
END KHBHDBN_COMPARE_PKG;
/
CREATE OR REPLACE PACKAGE BODY KHBHDBN_COMPARE_PKG AS
 FUNCTION D(p VARCHAR2) RETURN DATE IS x DATE; BEGIN x:=TO_DATE(TRIM(p),'FXDD-MM-YYYY'); RETURN TRUNC(x); EXCEPTION WHEN OTHERS THEN RAISE_APPLICATION_ERROR(-20981,'Ngay phai dung DD-MM-YYYY'); END;
 PROCEDURE GET_COMPARE(P_CURRENT_DATE IN VARCHAR2,P_COMPARE_DATE IN VARCHAR2,P_CATEGORY IN VARCHAR2 DEFAULT NULL,P_PAGE_SIZE IN NUMBER DEFAULT 100,P_PAGE_INDEX IN NUMBER DEFAULT 0,P_OUT_CURSOR OUT T_CURSOR) IS a DATE:=D(P_CURRENT_DATE); b DATE:=D(P_COMPARE_DATE); BEGIN OPEN P_OUT_CURSOR FOR
 'WITH c AS (SELECT ROW_NUMBER() OVER(PARTITION BY UPPER(TRIM(FLIGHTNBR)),UPPER(TRIM(FROM_AIRP)),UPPER(TRIM(TO_AIRP)) ORDER BY ETD,ETA,ROWID) rn,f.* FROM T_DAY_FLIGHTS f WHERE FLIGHTDATE>=:a AND FLIGHTDATE<:a+1 AND NVL(ISACCEPTED,1)=1 AND UPPER(TRIM(NVL(PERMNBR,''X''))) NOT LIKE ''NOPERM%''),p AS (SELECT ROW_NUMBER() OVER(PARTITION BY UPPER(TRIM(FLIGHTNBR)),UPPER(TRIM(FROM_AIRP)),UPPER(TRIM(TO_AIRP)) ORDER BY ETD,ETA,ROWID) rn,f.* FROM T_DAY_FLIGHTS f WHERE FLIGHTDATE>=:b AND FLIGHTDATE<:b+1 AND NVL(ISACCEPTED,1)=1 AND UPPER(TRIM(NVL(PERMNBR,''X''))) NOT LIKE ''NOPERM%''),x AS (SELECT c.FLIGHTNBR c_call,c.FROM_AIRP c_from,c.TO_AIRP c_to,c.ETD c_etd,c.ETA c_eta,c.CRAFT_ID c_craft,c.STATUS c_status,c.PERMNBR c_perm,p.FLIGHTNBR p_call,p.FROM_AIRP p_from,p.TO_AIRP p_to,p.ETD p_etd,p.ETA p_eta,p.CRAFT_ID p_craft,p.STATUS p_status,p.PERMNBR p_perm,CASE WHEN c.FLIGHTNBR IS NULL THEN ''MISSING'' WHEN p.FLIGHTNBR IS NULL THEN ''NEW'' WHEN c.ETD=p.ETD AND c.ETA=p.ETA AND c.FROM_AIRP=p.FROM_AIRP AND c.TO_AIRP=p.TO_AIRP AND NVL(c.CRAFT_ID,''X'')=NVL(p.CRAFT_ID,''X'') AND NVL(c.STATUS,''X'')=NVL(p.STATUS,''X'') THEN ''NORMAL'' ELSE ''CHANGED'' END CATEGORY FROM c FULL OUTER JOIN p ON UPPER(TRIM(c.FLIGHTNBR))=UPPER(TRIM(p.FLIGHTNBR)) AND UPPER(TRIM(c.FROM_AIRP))=UPPER(TRIM(p.FROM_AIRP)) AND UPPER(TRIM(c.TO_AIRP))=UPPER(TRIM(p.TO_AIRP)) AND c.rn=p.rn),z AS (SELECT x.*,CASE WHEN COUNT(*) OVER(PARTITION BY NVL(c_call,p_call),NVL(c_from,p_from),NVL(c_to,p_to))>1 THEN ''Trung so hieu/chang'' WHEN CATEGORY=''CHANGED'' THEN ''Khac gio, route, loai tau bay hoac trang thai'' END reason,ROW_NUMBER() OVER(ORDER BY CATEGORY,NVL(c_call,p_call)) rnum FROM x) SELECT z.*,COUNT(*) OVER() SUMRECORD FROM z WHERE (:cat IS NULL OR CATEGORY=:cat) AND rnum>:skip AND rnum<=:skip+:take' USING a,a,b,b,P_CATEGORY,P_CATEGORY,GREATEST(NVL(P_PAGE_INDEX,0),0)*GREATEST(NVL(P_PAGE_SIZE,100),1),GREATEST(NVL(P_PAGE_INDEX,0),0)*GREATEST(NVL(P_PAGE_SIZE,100),1),GREATEST(NVL(P_PAGE_SIZE,100),1); END;
 PROCEDURE GET_SUMMARY(P_CURRENT_DATE IN VARCHAR2,P_COMPARE_DATE IN VARCHAR2,P_OUT_CURSOR OUT T_CURSOR) IS a DATE:=D(P_CURRENT_DATE); b DATE:=D(P_COMPARE_DATE); BEGIN OPEN P_OUT_CURSOR FOR 'SELECT DIMENSION,DIMENSION_VALUE,SUM(CURRENT_COUNT) CURRENT_COUNT,SUM(PREVIOUS_COUNT) PREVIOUS_COUNT,SUM(CURRENT_COUNT)-SUM(PREVIOUS_COUNT) DELTA,ROUND((SUM(CURRENT_COUNT)-SUM(PREVIOUS_COUNT))*100/NULLIF(SUM(PREVIOUS_COUNT),0),2) PERCENT_DELTA FROM (SELECT ''AIRPORT'' DIMENSION,FROM_AIRP DIMENSION_VALUE,1 CURRENT_COUNT,0 PREVIOUS_COUNT FROM T_DAY_FLIGHTS WHERE FLIGHTDATE>=:a AND FLIGHTDATE<:a+1 UNION ALL SELECT ''AIRPORT'',FROM_AIRP,0,1 FROM T_DAY_FLIGHTS WHERE FLIGHTDATE>=:b AND FLIGHTDATE<:b+1 UNION ALL SELECT ''AIRPORT'',TO_AIRP,1,0 FROM T_DAY_FLIGHTS WHERE FLIGHTDATE>=:a AND FLIGHTDATE<:a+1 UNION ALL SELECT ''AIRPORT'',TO_AIRP,0,1 FROM T_DAY_FLIGHTS WHERE FLIGHTDATE>=:b AND FLIGHTDATE<:b+1 UNION ALL SELECT ''ROUTE'',FROM_AIRP||''-''||TO_AIRP,1,0 FROM T_DAY_FLIGHTS WHERE FLIGHTDATE>=:a AND FLIGHTDATE<:a+1 UNION ALL SELECT ''ROUTE'',FROM_AIRP||''-''||TO_AIRP,0,1 FROM T_DAY_FLIGHTS WHERE FLIGHTDATE>=:b AND FLIGHTDATE<:b+1 UNION ALL SELECT ''CARRIER'',SUBSTR(FLIGHTNBR,1,3),1,0 FROM T_DAY_FLIGHTS WHERE FLIGHTDATE>=:a AND FLIGHTDATE<:a+1 UNION ALL SELECT ''CARRIER'',SUBSTR(FLIGHTNBR,1,3),0,1 FROM T_DAY_FLIGHTS WHERE FLIGHTDATE>=:b AND FLIGHTDATE<:b+1) GROUP BY DIMENSION,DIMENSION_VALUE ORDER BY DIMENSION,DIMENSION_VALUE' USING a,a,b,b,a,a,b,b,a,a,b,b,a,a,b,b; END;
END KHBHDBN_COMPARE_PKG;
/
